/* app.css - minimal overrides */

/* Hide toggle and delete button while a todo is being edited */
li.editing .view .toggle,
li.editing .view .destroy {
	display: none;
}

const { Given, When, Then, After } = require('@cucumber/cucumber');
const fs = require('fs');
const path = require('path');
const { Window } = require('happy-dom');

let win;
let doc;

function loadApp(hash, localStorageState) {
  const indexHtml = fs.readFileSync(
    path.resolve(__dirname, '../../index.html'),
    'utf8'
  );
  const appJs = fs.readFileSync(
    path.resolve(__dirname, '../../js/app.js'),
    'utf8'
  );

  win = new Window({
    url: 'http://localhost:8080/' + (hash || ''),
    pretendToBeVisual: true,
  });

  doc = win.document;

  // Load HTML
  doc.write(indexHtml);
  doc.close();

  // Inject CSS files so getComputedStyle works
  const cssFiles = ['node_modules/todomvc-common/base.css', 'node_modules/todomvc-app-css/index.css', 'css/app.css'];
  cssFiles.forEach(function (cssFile) {
    const cssPath = path.resolve(__dirname, '../../' + cssFile);
    if (fs.existsSync(cssPath)) {
      const cssContent = fs.readFileSync(cssPath, 'utf8');
      const styleEl = doc.createElement('style');
      styleEl.textContent = cssContent;
      doc.head.appendChild(styleEl);
    }
  });

  // Restore localStorage before app init reads it
  if (localStorageState) {
    for (const [key, value] of Object.entries(localStorageState)) {
      win.localStorage.setItem(key, value);
    }
  }

  // Execute app.js via eval in window context
  win.eval(appJs);

  // Dispatch DOMContentLoaded
  const event = new win.Event('DOMContentLoaded');
  doc.dispatchEvent(event);

  // Simulate autofocus (happy-dom doesn't auto-focus)
  const newTodoInput = doc.querySelector('.new-todo');
  if (newTodoInput) newTodoInput.focus();
}

function teardown() {
  if (win) {
    win.close();
    win = null;
    doc = null;
  }
}

function createTodo(title) {
  const input = doc.querySelector('.new-todo');
  input.value = title;
  const event = new win.KeyboardEvent('keydown', { keyCode: 13, bubbles: true });
  input.dispatchEvent(event);
}

function findTodoLi(title) {
  const items = doc.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('.view label');
    if (label && label.textContent === title) {
      return items[i];
    }
  }
  return null;
}

// ── Background / setup ─────────────────────────────────────────────────
Given('the app is loaded', function () {
  loadApp();
});

// ── Creating todos ─────────────────────────────────────────────────────
When(
  'the user types {string} in the new-todo input and presses Enter',
  function (title) {
    createTodo(title);
  }
);

When('the user presses Enter in the new-todo input', function () {
  createTodo('');
});

Then('a todo item {string} appears in the list', function (title) {
  const li = findTodoLi(title);
  if (!li) throw new Error(`Todo "${title}" not found in list`);
});

Then('the new-todo input is empty', function () {
  const input = doc.querySelector('.new-todo');
  if (input.value !== '') {
    throw new Error(`Expected input to be empty, got "${input.value}"`);
  }
});

Then('no todo items appear in the list', function () {
  const items = doc.querySelectorAll('.todo-list li');
  if (items.length !== 0) {
    throw new Error(`Expected no todo items, found ${items.length}`);
  }
});

Then('the new-todo input has focus', function () {
  const input = doc.querySelector('.new-todo');
  if (doc.activeElement !== input) {
    throw new Error('new-todo input does not have focus');
  }
});

// ── Existing todos helper ──────────────────────────────────────────────
Given('the user has created a todo {string}', function (title) {
  createTodo(title);
});

// ── Counter ────────────────────────────────────────────────────────────
Then('the todo count shows {string}', function (text) {
  const countEl = doc.querySelector('.todo-count');
  const actual = countEl.textContent.trim();
  if (actual !== text) {
    throw new Error(`Expected count "${text}", got "${actual}"`);
  }
});

// ── Toggling ───────────────────────────────────────────────────────────
When('the user toggles the todo {string}', function (title) {
  const li = findTodoLi(title);
  if (!li) throw new Error(`Todo "${title}" not found`);
  const checkbox = li.querySelector('.toggle');
  checkbox.click();
});

Then('the todo {string} has the completed class', function (title) {
  const li = findTodoLi(title);
  if (!li) throw new Error(`Todo "${title}" not found`);
  if (!li.classList.contains('completed')) {
    throw new Error(`Todo "${title}" does not have completed class`);
  }
});

Then('the todo {string} does not have the completed class', function (title) {
  const li = findTodoLi(title);
  if (!li) throw new Error(`Todo "${title}" not found`);
  if (li.classList.contains('completed')) {
    throw new Error(`Todo "${title}" has completed class but should not`);
  }
});

// ── Deleting ───────────────────────────────────────────────────────────
When('the user deletes the todo {string}', function (title) {
  const li = findTodoLi(title);
  if (!li) throw new Error(`Todo "${title}" not found`);
  const destroyBtn = li.querySelector('.destroy');
  destroyBtn.click();
});

Then('the todo {string} is not in the list', function (title) {
  const li = findTodoLi(title);
  if (li) {
    throw new Error(`Todo "${title}" is still in the list`);
  }
});

Then('the todo {string} is in the list', function (title) {
  const li = findTodoLi(title);
  if (!li) {
    throw new Error(`Todo "${title}" is not in the list`);
  }
});

// ── Visibility ─────────────────────────────────────────────────────────
Then('the main section is hidden', function () {
  const main = doc.querySelector('.main');
  if (main.style.display !== 'none') {
    throw new Error('Main section is not hidden');
  }
});

Then('the footer is hidden', function () {
  const footer = doc.querySelector('.footer');
  if (footer.style.display !== 'none') {
    throw new Error('Footer is not hidden');
  }
});

Then('the main section is visible', function () {
  const main = doc.querySelector('.main');
  if (main.style.display === 'none') {
    throw new Error('Main section is hidden');
  }
});

Then('the footer is visible', function () {
  const footer = doc.querySelector('.footer');
  if (footer.style.display === 'none') {
    throw new Error('Footer is hidden');
  }
});

// ── Editing ────────────────────────────────────────────────────────────
When('the user double-clicks the todo label {string}', function (title) {
  const li = findTodoLi(title);
  if (!li) throw new Error(`Todo "${title}" not found`);
  const label = li.querySelector('.view label');
  const event = new win.Event('dblclick', { bubbles: true });
  label.dispatchEvent(event);
});

Then('the todo {string} has the editing class', function (title) {
  const li = findTodoLi(title);
  if (!li) throw new Error(`Todo "${title}" not found`);
  if (!li.classList.contains('editing')) {
    throw new Error(`Todo "${title}" does not have editing class`);
  }
});

Then('the edit input for {string} has focus', function (title) {
  const li = findTodoLi(title);
  if (!li) throw new Error(`Todo "${title}" not found`);
  const editInput = li.querySelector('.edit');
  if (doc.activeElement !== editInput) {
    throw new Error('Edit input does not have focus');
  }
});

Then('the edit input value is {string}', function (expectedValue) {
  const editingLi = doc.querySelector('.todo-list li.editing');
  if (!editingLi) throw new Error('No todo is being edited');
  const editInput = editingLi.querySelector('.edit');
  if (editInput.value !== expectedValue) {
    throw new Error(
      `Expected edit input value "${expectedValue}", got "${editInput.value}"`
    );
  }
});

Given('the user is editing the todo {string}', function (title) {
  const li = findTodoLi(title);
  if (!li) throw new Error(`Todo "${title}" not found`);
  const label = li.querySelector('.view label');
  const event = new win.Event('dblclick', { bubbles: true });
  label.dispatchEvent(event);
});

When(
  'the user changes the edit input to {string} and presses Enter',
  function (newTitle) {
    const editingLi = doc.querySelector('.todo-list li.editing');
    if (!editingLi) throw new Error('No todo is being edited');
    const editInput = editingLi.querySelector('.edit');
    editInput.value = newTitle;
    const event = new win.KeyboardEvent('keydown', {
      keyCode: 13,
      bubbles: true,
    });
    editInput.dispatchEvent(event);
  }
);

When(
  'the user changes the edit input to {string} and blurs',
  function (newTitle) {
    const editingLi = doc.querySelector('.todo-list li.editing');
    if (!editingLi) throw new Error('No todo is being edited');
    const editInput = editingLi.querySelector('.edit');
    editInput.value = newTitle;
    const event = new win.FocusEvent('blur', { bubbles: true });
    editInput.dispatchEvent(event);
  }
);

When('the user clears the edit input and presses Enter', function () {
  const editingLi = doc.querySelector('.todo-list li.editing');
  if (!editingLi) throw new Error('No todo is being edited');
  const editInput = editingLi.querySelector('.edit');
  editInput.value = '';
  const event = new win.KeyboardEvent('keydown', {
    keyCode: 13,
    bubbles: true,
  });
  editInput.dispatchEvent(event);
});

When(
  'the user changes the edit input to {string} and presses Escape',
  function (newTitle) {
    const editingLi = doc.querySelector('.todo-list li.editing');
    if (!editingLi) throw new Error('No todo is being edited');
    const editInput = editingLi.querySelector('.edit');
    editInput.value = newTitle;
    const event = new win.KeyboardEvent('keydown', {
      keyCode: 27,
      bubbles: true,
    });
    editInput.dispatchEvent(event);
  }
);

Then('the todo {string} does not have the editing class', function (title) {
  const li = findTodoLi(title);
  if (li && li.classList.contains('editing')) {
    throw new Error(`Todo "${title}" has editing class but should not`);
  }
});

// ── DOM identity ────────────────────────────────────────────────────────
let storedTodoElement = null;

Given('the DOM element for todo {string} is stored', function (title) {
  const li = findTodoLi(title);
  if (!li) throw new Error(`Todo "${title}" not found`);
  storedTodoElement = li;
});

Then('the todo {string} DOM element is still the same', function (title) {
  const li = findTodoLi(title);
  if (!li) throw new Error(`Todo "${title}" not found`);
  if (li !== storedTodoElement) {
    throw new Error(
      `Todo "${title}" DOM element was recreated (not preserved)`
    );
  }
});

// ── Edit mode visibility ────────────────────────────────────────────────
Then('the toggle checkbox for {string} is hidden', function (title) {
  const li = findTodoLi(title);
  if (!li) throw new Error(`Todo "${title}" not found`);
  const toggle = li.querySelector('.toggle');
  if (!toggle) throw new Error(`Toggle checkbox not found for "${title}"`);
  const style = win.getComputedStyle(toggle);
  if (style.display !== 'none') {
    throw new Error(
      `Toggle checkbox for "${title}" is not hidden (display: ${style.display})`
    );
  }
});

Then('the delete button for {string} is hidden', function (title) {
  const li = findTodoLi(title);
  if (!li) throw new Error(`Todo "${title}" not found`);
  const destroyBtn = li.querySelector('.destroy');
  if (!destroyBtn) throw new Error(`Delete button not found for "${title}"`);
  const style = win.getComputedStyle(destroyBtn);
  if (style.display !== 'none') {
    throw new Error(
      `Delete button for "${title}" is not hidden (display: ${style.display})`
    );
  }
});

// ── Toggle all ─────────────────────────────────────────────────────────
When('the user toggles the toggle-all checkbox', function () {
  const toggleAll = doc.querySelector('#toggle-all');
  toggleAll.click();
});

Then('the toggle-all checkbox is checked', function () {
  const toggleAll = doc.querySelector('#toggle-all');
  if (!toggleAll.checked) {
    throw new Error('Toggle-all checkbox is not checked');
  }
});

Then('the toggle-all checkbox is not checked', function () {
  const toggleAll = doc.querySelector('#toggle-all');
  if (toggleAll.checked) {
    throw new Error('Toggle-all checkbox is checked');
  }
});

// ── Clear completed ────────────────────────────────────────────────────
When('the user clicks the clear-completed button', function () {
  const btn = doc.querySelector('.clear-completed');
  btn.click();
});

Then('the clear-completed button is hidden', function () {
  const btn = doc.querySelector('.clear-completed');
  if (btn.style.display !== 'none') {
    throw new Error('Clear-completed button is not hidden');
  }
});

Then('the clear-completed button is visible', function () {
  const btn = doc.querySelector('.clear-completed');
  if (btn.style.display === 'none') {
    throw new Error('Clear-completed button is hidden');
  }
});

// ── Navigation / filtering ─────────────────────────────────────────────
function navigateTo(hash) {
  win.location.hash = hash;
  const event = new win.HashChangeEvent('hashchange', {
    oldURL: win.location.href,
    newURL: win.location.href,
    bubbles: true,
  });
  win.dispatchEvent(event);
}

When('the user navigates to {string}', navigateTo);

Then('the {string} filter is selected', function (filterName) {
  const filters = doc.querySelectorAll('.filters a');
  for (let i = 0; i < filters.length; i++) {
    if (filters[i].textContent === filterName) {
      if (!filters[i].classList.contains('selected')) {
        throw new Error(`Filter "${filterName}" is not selected`);
      }
      return;
    }
  }
  throw new Error(`Filter "${filterName}" not found`);
});

// ── Page reload ────────────────────────────────────────────────────────
When('the page is reloaded', function () {
  const hash = win.location.hash;
  // Capture all localStorage state
  const storageState = {};
  for (let i = 0; i < win.localStorage.length; i++) {
    const key = win.localStorage.key(i);
    storageState[key] = win.localStorage.getItem(key);
  }

  // Teardown and rebuild with preserved state
  teardown();
  loadApp(hash, storageState);
});

// ── Servable page (contract) ───────────────────────────────────────────
Given('the project root has an {string} file', function (filename) {
  const filePath = path.resolve(__dirname, '../../' + filename);
  if (!fs.existsSync(filePath)) {
    throw new Error(`File "${filename}" does not exist at project root`);
  }
});

let parsedDocument = null;

When('the file is parsed as HTML', function () {
  const filePath = path.resolve(__dirname, '../../index.html');
  const html = fs.readFileSync(filePath, 'utf8');
  const tempWin = new Window();
  tempWin.document.write(html);
  tempWin.document.close();
  parsedDocument = tempWin.document;
  // Keep reference alive for querySelector
  global.__parsedWindow = tempWin;
});

Then(
  'the document contains an element matching {string}',
  function (selector) {
    if (!parsedDocument) throw new Error('No document parsed');
    const el = parsedDocument.querySelector(selector);
    if (!el) {
      throw new Error(
        `Document does not contain an element matching "${selector}"`
      );
    }
  }
);

Then(
  'the document contains a script tag with source {string}',
  function (src) {
    if (!parsedDocument) throw new Error('No document parsed');
    const scripts = parsedDocument.querySelectorAll('script[src]');
    for (let i = 0; i < scripts.length; i++) {
      if (scripts[i].getAttribute('src') === src) {
        return;
      }
    }
    throw new Error(`No script tag with source "${src}" found`);
  }
);

// ── After hook ─────────────────────────────────────────────────────────
After(function () {
  teardown();
  parsedDocument = null;
});

(function () {
	'use strict';

	var ENTER_KEY = 13;
	var ESCAPE_KEY = 27;

	var todos = [];
	var selectedFilter = 'all';
	var editingId = null;

	var $ = function (sel) { return document.querySelector(sel); };
	var $$ = function (sel) { return document.querySelectorAll(sel); };

	function generateId() {
		return Date.now() + Math.random().toString(36).slice(2, 9);
	}

	function save() {
		localStorage.setItem('todos-javascript', JSON.stringify(todos));
	}

	function load() {
		try {
			todos = JSON.parse(localStorage.getItem('todos-javascript')) || [];
		} catch (e) {
			todos = [];
		}
	}

	function getActiveTodos() {
		return todos.filter(function (t) { return !t.completed; });
	}

	function getCompletedTodos() {
		return todos.filter(function (t) { return t.completed; });
	}

	function getVisibleTodos() {
		if (selectedFilter === 'active') {
			return getActiveTodos();
		}
		if (selectedFilter === 'completed') {
			return getCompletedTodos();
		}
		return todos;
	}

	function findTodo(title) {
		for (var i = 0; i < todos.length; i++) {
			if (todos[i].title === title) {
				return todos[i];
			}
		}
		return null;
	}

	function findTodoById(id) {
		for (var i = 0; i < todos.length; i++) {
			if (todos[i].id === id) {
				return todos[i];
			}
		}
		return null;
	}

	function pluralize(count) {
		return count === 1 ? 'item' : 'items';
	}

	function render() {
		var todoList = $('.todo-list');
		var main = $('.main');
		var footer = $('.footer');
		var toggleAll = $('#toggle-all');
		var todoCount = $('.todo-count');
		var clearCompleted = $('.clear-completed');
		var visibleTodos = getVisibleTodos();

		// Build a map of existing <li> elements keyed by id
		var existing = {};
		var existingItems = todoList.querySelectorAll('li[data-id]');
		for (var i = 0; i < existingItems.length; i++) {
			var eid = existingItems[i].getAttribute('data-id');
			existing[eid] = existingItems[i];
		}

		// Track which ids we are placing, in order
		var placedIds = [];

		visibleTodos.forEach(function (todo) {
			var li = existing[todo.id];
			if (li) {
				// Update existing element in place
				li.classList.toggle('completed', todo.completed);
				li.classList.toggle('editing', editingId === todo.id);
				li.querySelector('.toggle').checked = todo.completed;
				li.querySelector('label').textContent = todo.title;
				li.querySelector('.edit').value = todo.title;
			} else {
				// Create new element
				li = document.createElement('li');
				li.setAttribute('data-id', todo.id);
				if (todo.completed) {
					li.classList.add('completed');
				}
				if (editingId === todo.id) {
					li.classList.add('editing');
				}

				li.innerHTML =
					'<div class="view">' +
						'<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
						'<label>' + escapeHtml(todo.title) + '</label>' +
						'<button class="destroy"></button>' +
					'</div>' +
					'<input class="edit" value="' + escapeHtml(todo.title) + '">';

				todoList.appendChild(li);
			}
			placedIds.push(todo.id);
		});

		// Remove elements for todos no longer visible
		var allLi = todoList.querySelectorAll('li[data-id]');
		for (var j = 0; j < allLi.length; j++) {
			var liId = allLi[j].getAttribute('data-id');
			if (placedIds.indexOf(liId) === -1) {
				allLi[j].parentNode.removeChild(allLi[j]);
			}
		}

		if (todos.length === 0) {
			main.style.display = 'none';
			footer.style.display = 'none';
		} else {
			main.style.display = '';
			footer.style.display = '';
		}

		var activeCount = getActiveTodos().length;
		todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + pluralize(activeCount) + ' left';

		var allCompleted = todos.length > 0 && getActiveTodos().length === 0;
		toggleAll.checked = allCompleted;

		var completedCount = getCompletedTodos().length;
		clearCompleted.style.display = completedCount > 0 ? '' : 'none';

		$$('#filters a').forEach(function (a) {
			a.classList.remove('selected');
		});
		var filterMap = { all: '#/', active: '#/active', completed: '#/completed' };
		var selectedLink = document.querySelector('.filters a[href="' + filterMap[selectedFilter] + '"]');
		if (selectedLink) {
			selectedLink.classList.add('selected');
		}
	}

	function escapeHtml(text) {
		var div = document.createElement('div');
		div.appendChild(document.createTextNode(text));
		return div.innerHTML;
	}

	function addTodo(title) {
		var trimmed = title.trim();
		if (trimmed === '') {
			return;
		}
		todos.push({
			id: generateId(),
			title: trimmed,
			completed: false
		});
		save();
		render();
	}

	function toggleTodo(id) {
		var todo = findTodoById(id);
		if (todo) {
			todo.completed = !todo.completed;
			save();
			render();
		}
	}

	function destroyTodo(id) {
		todos = todos.filter(function (t) { return t.id !== id; });
		save();
		render();
	}

	function toggleAll() {
		var allCompleted = getActiveTodos().length === 0;
		todos.forEach(function (t) {
			t.completed = !allCompleted;
		});
		save();
		render();
	}

	function clearCompleted() {
		todos = getActiveTodos();
		save();
		render();
	}

	function startEditing(id) {
		editingId = id;
		render();
		var todo = findTodoById(id);
		if (todo) {
			var items = $$('.todo-list li');
			for (var i = 0; i < items.length; i++) {
				if (items[i].getAttribute('data-id') === id) {
					var editInput = items[i].querySelector('.edit');
					editInput.focus();
					editInput.setSelectionRange(editInput.value.length, editInput.value.length);
					break;
				}
			}
		}
	}

	function saveEdit(id, newTitle) {
		var trimmed = newTitle.trim();
		if (trimmed === '') {
			destroyTodo(id);
			return;
		}
		var todo = findTodoById(id);
		if (todo) {
			todo.title = trimmed;
			editingId = null;
			save();
			render();
		}
	}

	function cancelEdit() {
		editingId = null;
		render();
	}

	function handleHashChange() {
		var hash = window.location.hash || '#/';
		if (hash === '#/active') {
			selectedFilter = 'active';
		} else if (hash === '#/completed') {
			selectedFilter = 'completed';
		} else {
			selectedFilter = 'all';
		}
		render();
	}

	function getTodoIdFromEvent(e) {
		var target = e.target;
		while (target && target !== document) {
			if (target.tagName === 'LI' && target.getAttribute('data-id')) {
				return target.getAttribute('data-id');
			}
			target = target.parentNode;
		}
		return null;
	}

	function init() {
		load();
		handleHashChange();

		var newTodoInput = $('.new-todo');
		var todoList = $('.todo-list');
		var toggleAllBtn = $('#toggle-all');
		var clearCompletedBtn = $('.clear-completed');

		newTodoInput.addEventListener('keydown', function (e) {
			if (e.keyCode === ENTER_KEY) {
				addTodo(newTodoInput.value);
				newTodoInput.value = '';
			}
		});

		todoList.addEventListener('click', function (e) {
			var id = getTodoIdFromEvent(e);
			if (!id) {
				return;
			}
			if (e.target.classList.contains('toggle')) {
				toggleTodo(id);
			} else if (e.target.classList.contains('destroy')) {
				destroyTodo(id);
			}
		});

		todoList.addEventListener('dblclick', function (e) {
			var id = getTodoIdFromEvent(e);
			if (!id) {
				return;
			}
			if (e.target.tagName === 'LABEL') {
				startEditing(id);
			}
		});

